import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"Tensor API","link":"/api/SIMD-API/tensor_api/tensor_api"},{"text":"reg矢量计算","link":"/api/SIMD-API/tensor_api/reg_vector_compute/reg_vector_compute"},{"text":"矢量计算的搬入","link":"/api/SIMD-API/tensor_api/reg_vector_compute/vector_compute_load/vector_compute_load"},{"text":"copy（Unified Buffer到L1 Buffer高维切分数据搬运）","link":"/api/SIMD-API/tensor_api/reg_vector_compute/vector_compute_load/copy_ub_to_l1"}]},"headers":[],"relativePath":"api/SIMD-API/tensor_api/reg_vector_compute/vector_compute_load/copy_ub_to_l1.md","filePath":"api/SIMD-API/tensor_api/reg_vector_compute/vector_compute_load/copy_ub_to_l1.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":3,"title":"搬运参数推导","slug":"搬运参数推导","link":"#搬运参数推导"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"关键特性说明","slug":"关键特性说明","link":"#关键特性说明"},{"level":3,"title":"DataBlock粒度搬运","slug":"DataBlock粒度搬运","link":"#DataBlock粒度搬运"},{"level":3,"title":"连续和非连续搬运","slug":"连续和非连续搬运","link":"#连续和非连续搬运"},{"level":3,"title":"局部区域搬运","slug":"局部区域搬运","link":"#局部区域搬运"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788319986000}'),c={name:"api/SIMD-API/tensor_api/reg_vector_compute/vector_compute_load/copy_ub_to_l1.md"};function t(e,s,o,d,i,r){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>copy（Unified Buffer到L1 Buffer的数据搬运）</h1><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>本接口为试验接口，在后续版本中可能会调整或改进，不保证后续兼容性。请开发者在使用过程中关注后续版本更新。</p></div><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>tensor_api/tensor.h</code>，命名空间为<code>asc::te</code>。</p><p>该接口用于将Unified Buffer（UB）中的数据搬运到L1 Buffer。接口根据源、目的Tensor的存储位置自动选择<code>copy_ub_to_l1</code>通路，并根据Layout推导数据块个数、单块长度以及源、目的块间间隔，同时支持连续和非连续的高维切分数据搬运。</p><p>当前支持ND2ND、DN2DN、NZ2NZ和ZN2ZN搬运。源、目的Layout Pattern必须相同，搬运过程中不执行格式转换和数据类型转换，数据格式和内容保持不变。该通路可用于将矢量计算生成或预处理的数据转移到L1 Buffer，供后续矩阵计算或其他片上流程使用。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">DstTensor</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">SrcTensor</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">copy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">DstTensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">SrcTensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">)</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">Atom</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">DstTensor</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">SrcTensor</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">copy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">copy_atom</span><span class="o">&lt;</span><span class="n">Atom</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">atom</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">DstTensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">SrcTensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">)</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">DstTensor</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">SrcTensor</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">DstCoord</span><span class="p">,</span>
<span class="w">    </span><span class="k">typename</span><span class="w"> </span><span class="nc">SrcCoord</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">CopyShape</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">copy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">DstTensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">SrcTensor</span><span class="o">&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">DstCoord</span><span class="o">&amp;</span><span class="w"> </span><span class="n">dst_coord</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">SrcCoord</span><span class="o">&amp;</span><span class="w"> </span><span class="n">src_coord</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">CopyShape</span><span class="o">&amp;</span><span class="w"> </span><span class="n">copy_shape</span><span class="p">)</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">CopyOperation</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">make_copy</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">CopyOperation</span><span class="o">&amp;</span><span class="w"> </span><span class="n">operation</span><span class="p">)</span>

<span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">CopyOperation</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">CopyTrait</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="k">constexpr</span><span class="w"> </span><span class="k">auto</span><span class="w"> </span><span class="n">make_copy</span><span class="p">(</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">CopyOperation</span><span class="o">&amp;</span><span class="w"> </span><span class="n">operation</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">CopyTrait</span><span class="o">&amp;</span><span class="w"> </span><span class="n">trait</span><span class="p">)</span>
</code></pre></div><p>UB到L1 Buffer通路使用<code>copy_ub_to_l1{}</code>作为搬运操作对象，默认trait为<code>ub_to_l1_trait_default{}</code>。</p><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><table><thead><tr><th align="left">参数名</th><th align="center">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">atom</td><td align="center">输入</td><td align="left">搬运原子对象，可通过<code>make_copy(copy_ub_to_l1{})</code>或<code>make_copy(copy_ub_to_l1{}, ub_to_l1_trait_default{})</code>构造。</td></tr><tr><td align="left">dst</td><td align="center">输出</td><td align="left">目的Tensor，存储位置必须为<code>location::l1</code>。</td></tr><tr><td align="left">src</td><td align="center">输入</td><td align="left">源Tensor，存储位置必须为<code>location::ub</code>。</td></tr><tr><td align="left">dst_coord</td><td align="center">输入</td><td align="left">目的区域起始坐标。显式坐标的结构应与<code>copy_shape</code>一致，也可以使用<code>zero_coord</code>。</td></tr><tr><td align="left">src_coord</td><td align="center">输入</td><td align="left">源区域起始坐标。显式坐标的结构应与<code>copy_shape</code>一致，也可以使用<code>zero_coord</code>。</td></tr><tr><td align="left">copy_shape</td><td align="center">输入</td><td align="left">搬运区域的逻辑Shape。接口根据该Shape及源、目的Layout推导起始地址和搬运参数。</td></tr></tbody></table><h3 id="搬运参数推导">搬运参数推导<a class="header-anchor" href="#搬运参数推导">​</a></h3><p><code>copy</code>根据源、目的Tensor的Layout自动推导这些参数。单块长度和源、目的块间间隔均以DataBlock为单位，1个DataBlock为32字节。</p><p>对于整Tensor搬运，各Layout模式的推导规则如下。表中的“每个DataBlock的元素数”等于<code>32 / sizeof(T)</code>；对于b4类型，按对应的32字节搬运粒度计算。</p><table><thead><tr><th align="left">Layout模式</th><th align="left">数据块个数</th><th align="left">单块长度</th><th align="left">源、目的块间间隔</th></tr></thead><tbody><tr><td align="left">ND</td><td align="left">源Layout的总行数</td><td align="left">总列数除以每个DataBlock的元素数，向上取整</td><td align="left">对应Tensor的行步长减去总列数，再除以每个DataBlock的元素数并向上取整</td></tr><tr><td align="left">DN</td><td align="left">源Layout的总列数</td><td align="left">总行数除以每个DataBlock的元素数，向上取整</td><td align="left">对应Tensor的列步长减去总行数，再除以每个DataBlock的元素数并向上取整</td></tr><tr><td align="left">NZ</td><td align="left">分形格式的外层列数</td><td align="left">Layout的总行数</td><td align="left">对应Tensor的外层列步长除以每个DataBlock的元素数，再减去单块长度</td></tr><tr><td align="left">ZN</td><td align="left">分形格式的外层行数</td><td align="left">Layout的总列数</td><td align="left">对应Tensor的外层行步长除以每个DataBlock的元素数，再减去单块长度</td></tr></tbody></table><p>推导结果与<code>DataCopyParams</code>直接对应：数据块个数对应<code>blockCount</code>，单块长度对应<code>blockLen</code>，源、目的块间间隔分别对应<code>srcGap</code>和<code>dstGap</code>。调用<code>copy</code>时无需构造或传入<code>DataCopyParams</code>。</p><p>使用区域搬运重载时，接口根据<code>src_coord</code>、<code>dst_coord</code>和<code>copy_shape</code>解析起始地址和搬运区域。ND、DN模式按区域行列数推导参数；NZ、ZN模式还会结合分形内轴和Batch维度推导数据块个数。</p><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p>源Tensor和目的Tensor的数据类型必须相同。</p><table><thead><tr><th align="left">源/目的Layout</th><th align="left">支持的数据类型</th></tr></thead><tbody><tr><td align="left">ND、DN、NZ、ZN</td><td align="left"><code>fp4x2_e1m2_t</code>、<code>fp4x2_e2m1_t</code>、<code>int8_t</code>、<code>uint8_t</code>、<code>hifloat8_t</code>、<code>fp8_e5m2_t</code>、<code>fp8_e4m3fn_t</code>、<code>int16_t</code>、<code>uint16_t</code>、<code>half</code>、<code>bfloat16_t</code>、<code>int32_t</code>、<code>uint32_t</code>、<code>float</code>、<code>int64_t</code></td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p><code>copy</code>无返回值。<code>make_copy</code>返回<code>copy_atom</code>对象。</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>源Tensor必须位于UB，目的Tensor必须位于L1 Buffer。</li><li>源UB地址和目的L1 Buffer地址均需满足32字节对齐要求。</li><li>源、目的Layout Pattern必须相同。支持ND2ND、DN2DN、NZ2NZ和ZN2ZN，不支持随路格式转换。</li><li>源、目的数据类型必须相同，目的Tensor或目的区域容量必须不小于搬运区域。</li><li>搬运长度和源/目的间隔以32字节DataBlock为粒度。ND和DN区域大小不能整除DataBlock元素数时，接口按DataBlock粒度向上取整，调用方必须保证源、目的缓冲区具备相应空间。</li><li>Layout推导出的参数必须满足底层<code>asc_copy_ub2l1</code>指令的字段范围。有效搬运的数据块个数取值范围为[1, 4095]，单块长度取值范围为[1, 65535]个DataBlock，源、目的块间间隔取值范围均为[0, 65535]个DataBlock。</li><li>Tensor API要求源、目的Layout以及区域搬运Shape合法，不能依赖数据块个数或单块长度为0表示空操作。</li><li>连续执行多个<code>copy</code>且目的L1 Buffer区域存在重叠时，必须在两次搬运之间插入MTE2流水同步，例如调用<code>PipeBarrier&lt;PIPE_MTE2&gt;()</code>，避免后一次搬运覆盖前一次尚未完成的数据。</li></ul><h2 id="关键特性说明">关键特性说明<a class="header-anchor" href="#关键特性说明">​</a></h2><h3 id="DataBlock粒度搬运">DataBlock粒度搬运<a class="header-anchor" href="#DataBlock粒度搬运">​</a></h3><p>ND通路按行搬运，DN通路按列搬运。接口根据数据类型计算一个32字节DataBlock可容纳的元素数，并将逻辑搬运长度向上取整为DataBlock数量。NZ和ZN通路根据分形内轴直接推导DataBlock参数。</p><p>例如，<code>half</code>类型的一个DataBlock包含16个元素。搬运一行20个<code>half</code>元素时，单块长度向上取整为2个DataBlock，底层实际按32个<code>half</code>元素的空间处理。因此源、目的缓冲区及Layout步长必须覆盖向上取整后的范围。</p><h3 id="连续和非连续搬运">连续和非连续搬运<a class="header-anchor" href="#连续和非连续搬运">​</a></h3><p>源、目的块间间隔均为0时，相邻数据块首尾相接，属于连续搬运。任一块间间隔大于0时，属于非连续搬运；接口只搬运数据块覆盖的地址范围，不读取源间隔，也不写入目的间隔。当数据块个数为1时，块间间隔不影响搬运结果。</p><p>以官方<code>DataCopy</code>示例中的<code>half</code>数据为例，每个数据块包含8个DataBlock，即256字节：</p><table><thead><tr><th align="left">数据块个数</th><th align="left">单块长度</th><th align="left">源块间间隔</th><th align="left">目的块间间隔</th><th align="left">搬运效果</th></tr></thead><tbody><tr><td align="left">2</td><td align="left">8个DataBlock</td><td align="left">0</td><td align="left">1个DataBlock</td><td align="left">UB中的两个数据块连续读取；写入L1 Buffer时，两个数据块之间保留32字节间隔。</td></tr></tbody></table><h3 id="局部区域搬运">局部区域搬运<a class="header-anchor" href="#局部区域搬运">​</a></h3><p>区域重载支持在源、目的Tensor中指定不同的起始坐标。接口根据<code>copy_shape</code>和Layout Stride生成多块搬运，可用于将UB中的局部矩形区域写入L1 Buffer的指定位置。</p><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;tensor_api/tensor.h&quot;</span>

<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">M</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">N</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">64</span><span class="p">;</span>

<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">copy_ub_to_l1_example</span><span class="p">()</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">__ubuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">ub_buf</span><span class="p">[</span><span class="n">M</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">N</span><span class="p">];</span>
<span class="w">    </span><span class="n">__cbuf__</span><span class="w"> </span><span class="n">half</span><span class="w"> </span><span class="n">l1_buf</span><span class="p">[</span><span class="n">M</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">N</span><span class="p">];</span>

<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">layout</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_frame_layout</span><span class="o">&lt;</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">nd_ext_layout_ptn</span><span class="p">,</span>
<span class="w">        </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">layout_trait_default</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;&gt;</span><span class="p">(</span><span class="n">M</span><span class="p">,</span><span class="w"> </span><span class="n">N</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">src</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_tensor</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_mem_ptr</span><span class="o">&lt;</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">location</span><span class="o">::</span><span class="n">ub</span><span class="o">&gt;</span><span class="p">(</span><span class="n">ub_buf</span><span class="p">),</span><span class="w"> </span><span class="n">layout</span><span class="p">);</span>
<span class="w">    </span><span class="k">auto</span><span class="w"> </span><span class="n">dst</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_tensor</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_mem_ptr</span><span class="o">&lt;</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">location</span><span class="o">::</span><span class="n">l1</span><span class="o">&gt;</span><span class="p">(</span><span class="n">l1_buf</span><span class="p">),</span><span class="w"> </span><span class="n">layout</span><span class="p">);</span>

<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">copy</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">src</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div><p>该示例的ND Layout包含8行，每行64个<code>half</code>元素。一个DataBlock包含16个<code>half</code>元素，因此接口推导出<code>blockCount = 8</code>、<code>blockLen = 4</code>、<code>srcGap = 0</code>、<code>dstGap = 0</code>，属于连续搬运。</p><p>以下示例显式构造搬运原子对象，并搬运局部区域：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">auto</span><span class="w"> </span><span class="n">atom</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_copy</span><span class="p">(</span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">copy_ub_to_l1</span><span class="p">{},</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">ub_to_l1_trait_default</span><span class="p">{});</span>
<span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">copy</span><span class="p">(</span><span class="n">atom</span><span class="p">,</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">),</span><span class="w"> </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_coord</span><span class="p">(</span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">0</span><span class="p">),</span>
<span class="w">    </span><span class="n">asc</span><span class="o">::</span><span class="n">te</span><span class="o">::</span><span class="n">make_shape</span><span class="p">(</span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">));</span>
</code></pre></div><p>该区域包含2行，每行搬运32个<code>half</code>元素，单块长度为2个DataBlock。源、目的Tensor的行步长均为64个元素，每行有效区域之后均保留32个元素，即2个DataBlock，因此接口推导出<code>blockCount = 2</code>、<code>blockLen = 2</code>、<code>srcGap = 2</code>、<code>dstGap = 2</code>。</p></article></div>`,1)])])}const u=a(c,[["render",t]]);export{h as __pageData,u as default};
